-- Populate useful, research-informed qualification drafts for the existing job-description catalogue.
-- Remove only the known system-role seed prefix and exact generic placeholders.
-- Preserve non-empty HR-authored qualifications and keep all descriptions pending review.
-- This is a data-only migration; no runtime DDL and no approval-status changes.

UPDATE hr_job_description_templates
SET role_purpose = TRIM(SUBSTRING(
        role_purpose,
        CHAR_LENGTH('مسودة مستندة إلى مسارات النظام: ') + 1
    )),
    updated_at = CURRENT_TIMESTAMP
WHERE description_status <> 'approved'
  AND role_purpose LIKE 'مسودة مستندة إلى مسارات النظام: %';

UPDATE hr_job_description_templates
SET role_purpose = 'قيادة الجمعية وتوجيه الأولويات المؤسسية ومتابعة الأداء والحوكمة واتخاذ القرارات الإدارية ضمن الصلاحيات المعتمدة.',
    updated_at = CURRENT_TIMESTAMP
WHERE position_title = 'موظف'
  AND system_role_code = ''
  AND description_status <> 'approved'
  AND role_purpose = 'وصف عام مؤقت فقط: تنفيذ المهام التشغيلية التي يحددها القسم والمشرف المباشر كتابةً. يجب تخصيص المسؤوليات والصلاحيات لهذا الموظف قبل اعتماد الوصف.';

UPDATE hr_job_description_templates
SET responsibilities = '• تنفيذ الأعمال التشغيلية والإدارية المسندة ضمن نطاق القسم والصلاحيات المحددة.\n• تحديث السجلات والنماذج ذات الصلة بدقة وحفظ المستندات وفق الإجراءات المعتمدة.\n• التواصل مع المستفيدين والزملاء بمهنية وحماية البيانات الشخصية والسرية.\n• توثيق إنجاز المهام ورفع المخاطر والاستثناءات إلى المشرف المباشر.'
WHERE position_title = 'موظف'
  AND system_role_code = ''
  AND description_status <> 'approved'
  AND responsibilities = '• يحدد المشرف المباشر المهام اليومية والنتائج المتوقعة كتابةً.\n• الالتزام بسياسات الجمعية والسرية والحماية والسلامة.\n• توثيق العمل ورفع المخاطر أو التعارضات إلى المشرف.\n• هذه صياغة عامة غير كافية للاعتماد النهائي؛ يجب تخصيص المهام والصلاحيات قبل اعتماد الوصف.';

UPDATE hr_job_description_templates
SET qualifications = CASE
    WHEN system_role_code = 'general_manager' THEN '• مؤهل جامعي في الإدارة أو إدارة الأعمال أو الإدارة العامة أو مجال ذي صلة؛ وتُراعى خبرة قيادية مناسبة لطبيعة الجمعية.\n• خبرة في التخطيط المؤسسي والحوكمة وإدارة الفرق واتخاذ القرارات ومتابعة الأداء.\n• فهم للمساءلة وإدارة المخاطر وحماية الموارد والامتثال في المنظمات غير الربحية.\n• مهارات تواصل وتفاوض وكتابة تقارير بالعربية؛ والإنجليزية ميزة بحسب احتياجات الوظيفة.'
    WHEN system_role_code = 'vice_general_manager' THEN '• مؤهل جامعي في الإدارة أو إدارة الأعمال أو مجال ذي صلة، أو خبرة مهنية مكافئة مناسبة.\n• خبرة في تنسيق الأعمال بين الإدارات ومتابعة التنفيذ وإدارة الأولويات والتفويض.\n• مهارات تنظيم واتصال وكتابة تقارير وحل مشكلات، مع الالتزام بفصل الصلاحيات.'
    WHEN system_role_code = 'financial_manager' THEN '• مؤهل جامعي في المحاسبة أو المالية أو إدارة الأعمال مع تخصص مالي ذي صلة.\n• خبرة في المحاسبة والإقفال والتسويات وإعداد التقارير والرقابة المالية وإدارة الموازنات؛ وخبرة المنظمات غير الربحية ميزة مهمة.\n• إتقان جداول البيانات وبرامج المحاسبة أو ERP وفهم متطلبات التوثيق والتدقيق.\n• معرفة بالقواعد المالية والضريبية والعمل ذات الصلة في السودان؛ وشهادة مهنية مثل ACCA أو CPA ميزة إضافية وليست شرطاً مفترضاً.'
    WHEN system_role_code = 'accountant' THEN '• دبلوم عالٍ أو بكالوريوس في المحاسبة أو المالية أو مجال ذي صلة.\n• معرفة عملية بمبادئ المحاسبة والتسويات والمطابقات وحفظ المستندات وإعداد التقارير.\n• مهارات جيدة في Excel وبرامج المحاسبة، مع الدقة والنزاهة والقدرة على تتبع الأدلة.\n• خبرة محاسبية سابقة، وخصوصاً في منظمة غير ربحية، ميزة إضافية.'
    WHEN system_role_code = 'accountant_staff' THEN '• دبلوم أو مؤهل جامعي في المحاسبة أو المالية أو إدارة الأعمال، أو خبرة عملية مكافئة بحسب مستوى الوظيفة.\n• أساسيات المحاسبة وإدخال البيانات ومراجعة المستندات والمطابقات.\n• مهارات في Excel وبرامج المكتب وحفظ الملفات والتعامل الدقيق مع الأرقام.\n• الالتزام بالسرية وإحالة القرارات المالية إلى المسؤول المخول.'
    WHEN system_role_code = 'hr_manager' THEN '• مؤهل جامعي في الموارد البشرية أو إدارة الأعمال أو الإدارة أو القانون أو مجال ذي صلة.\n• خبرة في سجلات الموظفين والتوظيف والعقود وإدارة الأداء والحضور والإجازات والرواتب والسياسات.\n• معرفة عملية بمتطلبات العمل والموارد البشرية في السودان، مع مراجعة قانونية متخصصة عند الحاجة.\n• مهارات في أنظمة HR وجداول البيانات وإدارة السجلات والسرية وحل النزاعات؛ وخبرة القطاع غير الربحي ميزة.'
    WHEN system_role_code = 'hr_staff' THEN '• دبلوم أو بكالوريوس في الموارد البشرية أو إدارة الأعمال أو الإدارة أو مجال ذي صلة، أو خبرة عملية مكافئة.\n• مهارات في إدخال بيانات الموظفين وتنظيم الملفات ومتابعة الحضور والإجازات وإعداد بيانات الرواتب.\n• إتقان تطبيقات المكتب وجداول البيانات والتواصل المهني وحفظ السرية.\n• معرفة بإجراءات الموارد البشرية المحلية ميزة، على أن تُحدد المتطلبات النهائية من HR.'
    WHEN system_role_code IN ('admin','sudo') THEN '• مؤهل أو تدريب في تقنية المعلومات أو نظم المعلومات أو إدارة الأنظمة، أو خبرة تقنية عملية مكافئة.\n• معرفة بإدارة حسابات المستخدمين والصلاحيات واستكشاف الأعطال وأساسيات الشبكات وقواعد البيانات والنسخ الاحتياطي.\n• فهم لأمن المعلومات وحماية البيانات ومبدأ أقل صلاحية وتوثيق التغييرات.\n• خبرة في دعم تطبيقات الويب وبيئات الخوادم ميزة بحسب المهام الفعلية.'
    WHEN system_role_code = 'projects_manager' THEN '• مؤهل جامعي في إدارة المشروعات أو إدارة الأعمال أو التنمية أو مجال فني ذي صلة بالمشروعات التي تنفذها الجمعية.\n• خبرة في تخطيط المشروعات ودورة حياة المشروع ومتابعة الأنشطة والميزانية والمخاطر والتقارير.\n• مهارات تنسيق الفرق وإدارة أصحاب المصلحة وتوثيق النتائج والأدلة ومتابعة مؤشرات الأداء.\n• خبرة بالمنظمات غير الربحية ومتطلبات الجهات المانحة ميزة إضافية.'
    WHEN system_role_code = 'project_supervisor' THEN '• مؤهل أو تدريب مناسب لطبيعة القطاع أو المشروع، أو خبرة ميدانية مكافئة.\n• خبرة في متابعة الأنشطة الميدانية وتوثيق التقدم والمصروفات والأدلة ورفع المخاطر.\n• مهارات تنظيم وتواصل وإعداد تقارير واستخدام أدوات جمع البيانات.\n• معرفة بمبادئ الحماية والسلامة والمساءلة في العمل مع المجتمعات ميزة مهمة.'
    WHEN system_role_code = 'supervisor' THEN '• مؤهل أو تدريب مناسب في الإدارة أو الخدمة الاجتماعية أو مجال ذي صلة، أو خبرة عملية مناسبة.\n• مهارات تواصل ومتابعة ميدانية وخدمة مستفيدين وتنظيم سجلات دقيقة.\n• قدرة على استخدام النظام والنماذج الإلكترونية وحفظ سرية بيانات الكفلاء والأسر.\n• نزاهة وحسن تعامل والقدرة على تصعيد الطلبات المالية إلى الجهة المختصة.'
    WHEN system_role_code = 'nanny' THEN '• مؤهل أو تدريب مناسب في الرعاية أو التربية أو الخدمة الاجتماعية، أو خبرة عملية مناسبة بطبيعة العمل الفعلية.\n• مهارات تواصل وملاحظة وتوثيق ومتابعة احتياجات الأسر والأطفال ضمن الدور المحدد.\n• فهم مبادئ حماية الطفل والسرية واحترام المستفيدين والإبلاغ عن مخاوف الحماية.\n• القدرة على استخدام النماذج والسجلات التشغيلية؛ وتُحدد المؤهلات المطلوبة بعد مراجعة نطاق الوظيفة.'
    WHEN system_role_code = 'administration' THEN '• دبلوم أو مؤهل جامعي في الإدارة أو إدارة الأعمال أو مجال ذي صلة، أو خبرة عملية مكافئة.\n• مهارات خدمة مستفيدين ومتابعة الطلبات والاتصالات وتنظيم الملفات وتحديث السجلات.\n• مهارات استخدام الحاسوب وجداول البيانات والتواصل الكتابي والشفهي.\n• الالتزام بالدقة والسرية وإجراءات الإحالة وعدم تجاوز صلاحيات الإسناد أو الاعتماد.'
    WHEN system_role_code = 'social_media' THEN '• مؤهل أو تدريب في الإعلام أو الاتصال أو التسويق الرقمي أو مجال ذي صلة، أو ملف أعمال وخبرة عملية مناسبة.\n• مهارات كتابة وتحرير باللغة العربية، وإعداد محتوى رقمي واستخدام منصات التواصل وأدوات التصميم أو التحرير المناسبة.\n• القدرة على مراجعة المعلومات والتقيد بالهوية المؤسسية والحصول على الموافقات قبل النشر.\n• فهم الخصوصية والموافقة وحماية المستفيدين وعدم نشر بياناتهم أو صورهم دون الإذن المطلوب.'
    WHEN system_role_code = 'staff' THEN '• مؤهل دراسي أو تدريب مناسب لطبيعة المهام المسندة، أو خبرة عملية مكافئة.\n• مهارات تنظيم وإدخال بيانات واستخدام تطبيقات المكتب والتواصل مع الفريق والمستفيدين.\n• القدرة على اتباع الإجراءات وتوثيق العمل بدقة وحماية المعلومات والسرية.\n• تُحدد المؤهلات المتخصصة وفق المهام الفعلية للقسم قبل اعتماد الوصف.'
    WHEN position_title = 'المدير العام' THEN '• مؤهل جامعي في الإدارة أو إدارة الأعمال أو الإدارة العامة أو مجال ذي صلة؛ وتُراعى خبرة قيادية مناسبة لطبيعة الجمعية.\n• خبرة في التخطيط والحوكمة وإدارة الفرق ومتابعة الأداء والمساءلة.\n• مهارات اتخاذ القرار والتواصل وإدارة المخاطر؛ وخبرة القطاع غير الربحي ميزة إضافية.'
    WHEN position_title = 'نائب المدير العام' THEN '• مؤهل جامعي في الإدارة أو إدارة الأعمال أو مجال ذي صلة، أو خبرة مهنية مكافئة.\n• خبرة في التنسيق الإداري ومتابعة تنفيذ الخطط وإدارة الأولويات والتفويض.\n• مهارات تنظيم وتواصل وكتابة تقارير وحل المشكلات.'
    WHEN position_title = 'المدير المالي' THEN '• مؤهل جامعي في المحاسبة أو المالية أو إدارة الأعمال مع تخصص مالي ذي صلة.\n• خبرة في المحاسبة والتسويات والإقفال والتقارير والرقابة المالية والموازنات.\n• إتقان جداول البيانات وبرامج المحاسبة؛ وشهادة مهنية وخبرة المنظمات غير الربحية ميزتان إضافيتان.'
    WHEN position_title = 'مدير الموارد البشرية' THEN '• مؤهل جامعي في الموارد البشرية أو إدارة الأعمال أو الإدارة أو القانون أو مجال ذي صلة.\n• خبرة في التوظيف والعقود وسجلات الموظفين والحضور والإجازات والرواتب والسياسات.\n• مهارات في أنظمة HR وجداول البيانات والسرية والتواصل المهني.'
    WHEN position_title = 'مدير النظام' THEN '• مؤهل أو تدريب في تقنية المعلومات أو نظم المعلومات أو خبرة عملية مكافئة.\n• معرفة بإدارة المستخدمين والصلاحيات واستكشاف الأعطال وأمن المعلومات والنسخ الاحتياطي.\n• مهارات توثيق التغييرات وحماية البيانات ودعم التطبيقات.'
    WHEN position_title = 'محاسب' THEN '• دبلوم عالٍ أو بكالوريوس في المحاسبة أو المالية أو مجال ذي صلة.\n• معرفة بالمبادئ المحاسبية والمطابقات والتسويات وإعداد التقارير وحفظ المستندات.\n• إتقان Excel وبرامج المحاسبة؛ وخبرة القطاع غير الربحي ميزة إضافية.'
    WHEN position_title = 'مشرف مشروع' THEN '• مؤهل أو تدريب مناسب لطبيعة المشروع أو القطاع، أو خبرة ميدانية مكافئة.\n• خبرة في متابعة الأنشطة والجدول التشغيلي وتوثيق التقدم والمخاطر والأدلة.\n• مهارات إعداد التقارير والتواصل والتنظيم ومبادئ الحماية والسلامة.'
    WHEN position_title = 'مشرف' THEN '• مؤهل أو تدريب مناسب في الإدارة أو الخدمة الاجتماعية أو مجال ذي صلة، أو خبرة عملية مكافئة.\n• مهارات تواصل ومتابعة ميدانية وتنظيم سجلات واستخدام الحاسوب.\n• الالتزام بالسرية والدقة وإجراءات التصعيد.'
    WHEN position_title = 'مندوب استرجاع الكفلاء' THEN '• مؤهل أو تدريب مناسب في خدمة العملاء أو الإدارة أو الاتصال، أو خبرة عملية مكافئة.\n• مهارات تواصل وإقناع محترم وتوثيق المكالمات والمتابعات وإعداد التقارير.\n• استخدام الحاسوب وحماية بيانات الكفلاء والالتزام بالرسائل والسياسات المعتمدة.'
    WHEN position_title = 'موظف العلاقات العامة والإعلام' THEN '• مؤهل أو تدريب في الإعلام أو العلاقات العامة أو الاتصال أو التسويق الرقمي، أو خبرة/ملف أعمال مكافئ.\n• مهارات كتابة وتحرير وتنسيق فعاليات وإعداد محتوى رقمي واستخدام أدوات المكتب.\n• الالتزام بالموافقات التحريرية والهوية المؤسسية والخصوصية وحماية المستفيدين.'
    WHEN position_title = 'أخصائية شؤون الأمهات' THEN '• مؤهل أو تدريب في الخدمة الاجتماعية أو علم النفس أو التنمية المجتمعية أو مجال ذي صلة، أو خبرة عملية مكافئة.\n• مهارات تواصل داعم وإدارة ملفات وتوثيق ومتابعة إحالات مع احترام السرية والكرامة.\n• معرفة بمبادئ الحماية والسلامة والإبلاغ عن مخاوف الحماية؛ وتُحدد المؤهلات النهائية بعد تأكيد نطاق الوظيفة.'
    WHEN position_title = 'موظف' THEN '• مؤهل أو تدريب مناسب لطبيعة مهام القسم، أو خبرة عملية مكافئة.\n• مهارات أساسية في التواصل والتنظيم واستخدام الحاسوب وتوثيق العمل.\n• الالتزام بالدقة والسرية وسياسات الجمعية؛ وتُضاف أي مؤهلات تخصصية بعد تحديد المهام الفعلية.'
    ELSE qualifications
END,
updated_at = CURRENT_TIMESTAMP
WHERE description_status <> 'approved'
  AND (qualifications IS NULL
   OR TRIM(qualifications) = ''
   OR qualifications = 'مسودة مقترحة غير معتمدة: تُحدد المؤهلات العلمية والخبرة والمهارات المطلوبة بالتناسب مع المهام الفعلية وبمراجعة الموارد البشرية والمشرف المختص. لا تُعد هذه العبارة شرط توظيف رسمياً ولا تستبدل متطلبات قانونية أو مهنية واجبة.');
